Following the convention for (non-boundaried) graphs, we define a boundaried plane graph as a pair $(G,T)$, where $G$ is a plane graph and $T \subseteq V(G)$.

\paragraph*{Planarity criteria} \label{sec:prelims:criteria}

Let $G$ be a graph, $v \in V(G)$, and $S \subseteq V(G) \setminus \{v\}$.
We say that~\emph{$S$ planarizes~$v$} \mic{or $S$ is $v$-planarizing} if~$R_S[v,S]$ induces a  planar subgraph of $G$. 

\bmp{In a graph~$G$ we say that a sequence of pairwise disjoint vertex sets $(S_1, \dots, S_m)$ is \emph{nested} with respect to $v$ if for each~$i \in [m-1]$ the set~$S_i$ is a restricted~$(v,S_{i+1})$-separator. Note that this is equivalent to stating that~$v \notin \bigcup_{i=1}^m S_i$ and $R_G(v,S_i) \subseteq R_G(v,S_{i+1})$ for each $i \in [m-1]$.}

\bmp{Similarly, for~$\ell \in \mathbb{N}$ and two vertices~$v_0, v_{\ell+1}$ in a graph~$G$, a sequence of vertex-disjoint restricted $(v_0, v_{\ell+1})$-separators~$(S_i)_{i=1}^\ell$ is \emph{nested} if~$S_i$ is a $(S_{i-1}, S_{i+1})$-separator \bmp{for each~$i \in [\ell]$}, interpreting~$S_0 = \{v_0\}$ and~$S_{\ell+1} = \{v_{\ell+1}\}$. This implies that~$(S_1, \ldots, S_m)$ is nested with respect to~$v_0$, while the reverse sequence is nested with respect to~$v_{\ell+1}$.}

\begin{restatable}{lemma}{restPrelimCriterionNew}
\label{lem:prelim:criterion:new}
Let $v_0,v_4 \in V(G)$ and let $S_1,S_2,S_3 \subseteq V(G)$ be disjoint nested restricted $(v_0,v_4)$-separators \bmp{in a connected graph~$G$}, so that $G[S_i]$ is connected for each~$i \in [3]$. If $R_G[v_0,S_3]$ and $R_G[v_4,S_1]$ induce planar graphs, then~$G$ is planar.
\end{restatable}

\paragraph*{Irrelevant and necessary vertices}

Let $G$ be a graph.
We say that a vertex $v \in V(G)$ (resp. an edge $e \in E(G)$) is $k$-irrelevant in $G$ if for every vertex set $S \subseteq V(G)$ of size at most $k$, we have that $G-S$ is planar if and only if $(G-v) - S$ 
(resp. $(G \setminus e) - S$)
is planar.

\subsection{Protrusion replacement}

An $r$-protrusion in a graph $G$ is a vertex set $X \subseteq V(G)$, such that $|\partial_G(X)| \le r$ and $\text{tw}(G[X]) \le r$.
\mic{For a vertex set $X \subseteq V(G)$ with $|\partial_G(X)| = r$, a bijection $\lambda \colon [r] \to \partial_G(X)$, and a labeled $r$-boundaried graph $H$, the act of replacing $X$ by $H$ through $\lambda$ means (1) creating labeled $r$-boundaried graphs $H^X = (G[X], \partial_G(X), \lambda)$, $H^{V(G) \setminus X} = (G[(V(G) \setminus X) \cup \partial_G(X)], \partial_G(X), \lambda)$, and (2)
replacing $G =H^{V(G) \setminus X} \oplus H^X $ by $G' = H^{V(G) \setminus X} \oplus H$.
The graph $H^X$ is introduced above only for the sake of giving a more detailed view on the process.
We say that $G'$ is obtained from $G$ by replacing a set $X \subseteq V(G)$ if there exist $H, \lambda$ so that $X$ is replaced  by $H$ through $\lambda$.}

In such a problem we are given a graph~$G$ 
and the objective is to find a set $S \subseteq V(G)$ minimizing $|S|$ such that the
predicate $P_\Pi(G, S)$, expressible in \bmp{Counting Monadic Second-Order} (\textsc{CMSO}) logic, is satisfied.
For our purposes it is only relevant that this definition captures the \planardel problem.

\begin{definition}[Lossless Protrusion Replacer \cite{fomin2012planar, fomin2020planar-arxiv}]
\label{def:protrusion:replacer}
A lossless protrusion replacer for a \textsc{min-CMSO}
 vertex subset problem $\Pi$ is a family of algorithms, with one algorithm for every
constant $r$. The $r$-th algorithm has the following specifications. There exists a constant $\gamma(r)$
such that given an instance $G$ and an $r$-protrusion $X$ in $G$ containing at least $\gamma(r)$ vertices, $|\partial_G(X)| = r' \le r$, the
algorithm runs in polynomial time and outputs an instance $G'$ with the following properties.
\begin{itemize}
    \item $G'$ is obtained from $G$ by replacing $(G[X], \partial_G(X))$ by a labeled $r'$-boundaried graph $H$ with less than $\gamma(r)$ vertices, through some labeling $\lambda \colon [r'] \to \partial_G(X)$, and thus $V(G') < V(G)$.
    \item $\mathsf{OPT}(G') \le \mathsf{OPT}(G)$.
    \item There is an algorithm that runs in polynomial time and, given a feasible solution $S'$
to $G'$,
outputs a~set $X^* \subseteq  X$ such that $S = (S' \setminus V(H)) \cup X^*$ is a feasible solution to $G$ and
$|S| \le |S'| + \mathsf{OPT}(G) - \mathsf{OPT}(G')$.
\end{itemize}
\end{definition}

\begin{lemma}\label{lem:protrusion:planar-deletion}
The \planardel problem admits a lossless protrusion replacer.
Moreover, the choice of the replacement $H$ and the transposition value $\mvp(G) - \mvp(G')$ depends only on the labeled boundaried graph $(G[X], \partial_G(X), \lambda)$.
\end{lemma}

\begin{lemma}\label{lem:protrusion:reduce-treewidth}
Let $G$ be a graph, $A \subseteq V(G)$, and $G\brb A$ be a $(\le r)$-boundaried connected planar graph.
If $\text{tw}(G \brb A) > 27(2r+7)(r+1)$, then there exists a
vertex $v \in A$ and a sequence of $r+3$ connected pairwise-disjoint $(v,N_G(A))$-separators in $G\brb A$.
Such \bmp{a} vertex $v$ can be found in polynomial time, when given $G$ and $A$.
Furthermore, given $G,A,v$, and a planar modulator $S$ in $G-v$, one can find, in  time $n^{\Oh(r)}$, a planar modulator in $G$ of size at most $|S|$. 
\end{lemma}

\subsection{Outerplanar decomposition}

\begin{definition}[{\cite[Definition 5.1]{JansenPvL19-arxiv}}]
\label{def:diameter:outerplanarity-layers}
Let~$G$ be a plane graph. The outerplanarity layers of~$G$ form a partition of~$V(G)$ into~$L_1, \ldots, L_m$ defined recursively. The vertices incident with the outer face of~$G$ belong to layer~$L_1$. If~$v \in V(G)$ lies on the outer face of the plane subgraph obtained from~$G$ by removing~$L_1, \ldots, L_i$, then~$v$ belongs to layer~$L_{i+1}$. For a vertex~$v \in V(G)$, the unique index~$i \in [m]$ for which~$v \in L_i$ is the \emph{outerplanarity index} of~$v$ and denoted~$\opindex_G(v)$.
\end{definition}

\begin{definition}[{\cite[Definition 5.2]{JansenPvL19-arxiv}}]
For a plane graph~$G$, let~$T$ be the simple graph obtained by simultaneously contracting all edges~$uv$ whose endpoints belong to the same outerplanarity layer, discarding loops and parallel edges. For a node~$u \in V(T)$, let~$\kappa(u) \subseteq V(G)$ denote the vertex set of~$G$ whose contraction resulted in~$u$. 
Let~$\opindex_G(u)$ denote the outerplanarity index that is shared by all nodes in~$\kappa(u)$.
\end{definition}

\begin{lemma}[{\cite[Lemma 5.3]{JansenPvL19-arxiv}}] \label{lem:diamater:outerplanar-properties}
For a connected plane graph~$G$ and its outerplanar decomposition $(T,\kappa)$ based on the outerplanarity layers~$L_1, \ldots, L_m$, the following holds:
\begin{enumerate}
	\item $T$ is a tree.\label{prop:tree}
	\item For any node~$u \in V(T)$, the graph~$G[\kappa(u)]$ is connected.\label{prop:connected} \item If~$x,y$ are distinct vertices of~$T$, then for any internal node~$z$ of the unique $(x,y)$-path in~$T$, the set~$\kappa(z)$ is a restricted $(\kappa(x), \kappa(y))$-separator in~$G$.\label{prop:cut}
	\item There is a unique node~$x_1 \in V(T)$ such that~$\kappa(x_1) = L_1$. \label{prop:root:layer}
	\item Root~$T$ at vertex~$x_1$. If~$u \in V(T)$ is a child of~$p \in V(T)$, then~$\opindex_G(u) = 1+\opindex_G(p)$.\label{prop:idx:child}
\end{enumerate}
\end{lemma}

We call the pair $(T,\kappa)$, where $T$ is the tree rooted at $x_1$ accordingly to \cref{lem:diamater:outerplanar-properties}, the \emph{outerplanar decomposition} of $G$. 
Note that it is uniquely defined for a given \bmp{connected} plane graph $G$.
Let $\delta_T$ denote the shortest path distance on the tree $T$.
For distinct $x,y \in V(T)$ we define $T^P_{x,y}$ to be the unique $(x,y)$-path in $T$ and for non-adjacent  $x,y \in V(T)$ we define $T_{x,y}$ to be the connected component of $T-\{x,y\}$ containing the internal vertices of $T^P_{x,y}$.
\mic{For a subtree $T'$ of $T$ we use the notation $\kappa(T')$ to denote the union of $\{\kappa(t) \mid t \in V(T')\}$.}
Note that $N_G(\kappa(T_{x,y})) \subseteq \kappa(x) \cup \kappa(y)$.

\begin{observation}[{\cite[Observation 5.4]{JansenPvL19-arxiv}}]
\label{lem:diameter:outerplanar-faces}
Let $G$ be a connected plane graph and $(T,\kappa)$ be its outerplanar decomposition.
If $u, v \in V(G)$ share a face, then either there is  $x \in V(T)$ such that $u, v \in \kappa(x)$
or there are $x, y \in V(T)$
which are adjacent in $T$ and $u \in \kappa(x), v \in \kappa(y)$.
Conversely, if $x$ is a child of~$y$ in~$T$ 
and $v \in \kappa(x)$, then there exists $u \in \kappa(y)$, so that $u,v$ share a face.
\end{observation}

\mic{We define the depth of a rooted tree as the longest root-leaf distance plus 1 (so a singleton tree has depth 1).}

\begin{lemma}\label{lem:diameter:outerplanar-diameter}
Let $G$ be a connected plane graph and $(T,\kappa)$ be its outerplanar decomposition.
If the maximal depth in $T$ is $d$, then the radial diameter of $G$ is at most $2d-1$.
\end{lemma}

\begin{observation}
\label{lem:diameter:outerplanar-separator}
Let $G$ be a connected plane graph and $(T,\kappa)$ be its outerplanar decomposition.
Let $x, y, z \in V(T)$ be distinct pairwise non-adjacent vertices \bmp{such that} $z$ lies on the unique $(x,y)$-path in $T$.
Suppose that $S \subseteq V(G)$ is a restricted $(\kappa(z), \kappa(x) \cup \kappa(y))$-separator.
Then the connected component of $G - S$ containing $\kappa(z)$ is contained in $\kappa(T_{x,y})$.
\end{observation}

\subsection{Compressing the outerplanarity layers}

\begin{lemma}\label{lem:diameter:middle-layers}
Let $G$ be a graph, $A \subseteq V(G)$, $H$ be a \mic{connected} boundaried plane graph given by some plane embedding of $G \brb A$,
$(T,\kappa)$ be the outerplanar decomposition of $H$, and $k$ be an integer.
Consider vertices $x,y \in V(T)$ such that $x$ is an ancestor of $y$, $\delta_T(x,y) > 4k + 11$, $\kappa(T_{x,y}) \cap \partial(H) = \emptyset$,
and there are 6 internally vertex-disjoint $(\kappa(x), \kappa(y))$-paths in the graph $H \brb {\kappa(T_{x,y})}$.
There is a polynomial-time algorithm that, given all the above, returns a vertex set $V_D \subseteq \kappa(T_{x,y})$ and an edge set $E_D \subseteq E_G(\kappa(T_{x,y}), \kappa(T_{x,y}))$ so that the following hold.
\begin{enumerate}
    \item For each vertex $v \in \kappa(y)$ there exists a vertex $u \in \kappa(x)$ so that the radial distance between $u$ and $v$ in $H' = (H \setminus E_D) - V_D$ is at most $4k + 11$.\label{lem:diameter:middle-layers:distance}
    \item The boundaried graph $H' = (H \setminus E_D) - V_D$ is connected.
    \item Given a planar modulator $S'$ in $G' = (G \setminus E_D) - V_D$, such that $|S' \cap \kappa(T_{x,y})| \le k$, one can turn it, in polynomial time, into a planar modulator $S$ in $G$ such that $|S| \le |S'| + 2 \cdot |S' \cap \kappa(T_{x,y})|$ and $S \setminus \kappa(T_{x,y}) = S' \setminus \kappa(T_{x,y})$.\label{lem:diameter:middle-layers:lifting}
\end{enumerate}
\end{lemma}
